def cmd_status(app, args_str=''):
    """/status — 查看 agent 运行时状态。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    snap = app.status_snapshot()
    # 追加 5 类能力计数
    snap['capability_counts'] = {
        'skills': len(app.skills.list_skills()),
        'metaskills': len(app.metaskills.list_metaskills()),
        'tools': len(app.tools.list_tools()),
        'commands': len(app.commands.list_commands()),
        'agents': 1,  # 自身
    }
    lines = [
        '═══ 数字员工状态 ═══',
        'Agent ID : %s' % snap['agent_id'],
        'UID      : %s' % snap['uid'],
        'Home     : %s' % snap['home'],
        'Uptime   : %ds' % snap['uptime'],
        'LLM      : %s' % ('已配置' if snap['llm_configured'] else '未配置'),
        'Token    : 已用 %s' % snap['token'],
        '─── 能力计数 ───',
        '  技能(Skill)     : %d' % snap['capability_counts']['skills'],
        '  元技能(MetaSkill): %d' % snap['capability_counts']['metaskills'],
        '  工具(Tool)      : %d' % snap['capability_counts']['tools'],
        '  指令(Command)   : %d' % snap['capability_counts']['commands'],
        '  协作(Agent)     : %d' % snap['capability_counts']['agents'],
        '─── 记忆 ───',
        '  %s' % snap['memory_stats'],
    ]
    return '\n'.join(lines)


def cmd_skills(app, args_str=''):
    """/skills — 列出已装备的技能。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    skills = app.skills.list_skills()
    metaskills = app.metaskills.list_metaskills()

    lines = ['═══ 技能清单 ═══']
    if skills:
        lines.append('── Skill（业务技能）──')
        for s in skills:
            lines.append('  • %s (v%s) [%s]: %s' % (
                s['name'], s.get('version', '?'), s.get('source', '?'),
                s.get('description', '')))
    else:
        lines.append('（无业务技能）')

    lines.append('')
    if metaskills:
        lines.append('── MetaSkill（元技能）──')
        for m in metaskills:
            lines.append('  • %s (v%s) [%s]: %s' % (
                m['name'], m.get('version', '?'), m.get('source', '?'),
                m.get('description', '')))
    else:
        lines.append('（无元技能）')

    return '\n'.join(lines)


def cmd_reload(app, args_str=''):
    """/reload — 重新扫描 skills / metaskills 目录。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    app.skills = type(app.skills)(app.config, app.dag)
    app.metaskills.scan()
    skill_count = len(app.skills.list_skills())
    meta_count = len(app.metaskills.list_metaskills())
    return ('重新扫描完成：Skill %d 个，MetaSkill %d 个' % (
        skill_count, meta_count))


def cmd_learn(app, args_str=''):
    """/learn — 触发探索期。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    try:
        from agent_runtime.explore.explore_runner import ExploreRunner
        runner = ExploreRunner(app.config, app.llm, app.skills)
        result = runner.explore(args_str or None)
        return result
    except ImportError:
        return {'success': False, 'error': 'explore_runner 模块不可用'}
    except Exception as e:
        return {'success': False, 'error': str(e)}


