def cmd_trace(app, args_str=''):
    """/trace — 返回最近 DAG 执行轨迹。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    logs = app.memory.get_execution_logs(limit=10)
    if not logs:
        return '（无最近执行记录）'
    lines = ['═══ 最近执行轨迹 ═══']
    for entry in logs:
        lines.append('  [%s] intent=%s skill=%s status=%s' % (
            entry.get('timestamp', '?'),
            entry.get('intent', ''),
            entry.get('skill', ''),
            entry.get('status', '')))
    return '\n'.join(lines)


