def cmd_qoder(app, args_str=''):
    """\u002fqoder — 调用 Qoder CLI 子 Agent 执行开发任务。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    if not args_str.strip():
        return ('用法: /qoder <任务描述>\n'
                '示例: /qoder 用 Python 写一个冒泡排序并保存到 bubble_sort.py')

    # 检查 qoder provider 是否已注册
    if 'qoder' not in app.subagent_manager.providers:
        return ('Qoder 子 Agent 未注册。请确认：\n'
                '1. config.json 中 qoder_enabled = true\n'
                '2. qodercli 已安装')

    import asyncio
    import uuid
    from pathlib import Path
    from datetime import datetime
    from agent_runtime.core.subagent import SubagentRequest

    # 每次调用生成独立 task-xxx 工作空间，隔离不同任务的代码和日志
    task_id = 'task-%s' % uuid.uuid4().hex[:12]
    task_ws = Path(app.config.home) / 'workspace' / 'projects' / 'proj-default' / 'tasks' / task_id
    task_ws.mkdir(parents=True, exist_ok=True)
    cwd = str(task_ws)

    # 创建任务日志文件
    log_file = task_ws / ('%s.log' % task_id)
    log_file.write_text(
        'Qoder 任务执行日志\n'
        '==================\n'
        '任务 ID: %s\n'
        '创建时间: %s\n'
        '工作目录: %s\n'
        '任务描述: %s\n'
        '==================\n\n' % (
            task_id,
            datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            task_ws,
            args_str.strip(),
        )
    )

    # 注入 app，供后续可能的嵌套调用
    app._current_task_workspace = cwd

    # 在数据库中创建任务记录，使其出现在任务管理面板
    try:
        app.db.create_task(
            task_id=task_id,
            message=args_str.strip(),
            kind='chat',
            priority=5,
        )
        app.db.cas_transition(task_id, 'pending', 'running',
                              message='Qoder 开始执行')
    except Exception:
        logger.debug('Qoder 任务记录创建失败（不影响执行）', exc_info=True)

    async def _run():
        request = SubagentRequest(
            task=args_str.strip(),
            provider='qoder',
            timeout_ms=app.config.get('qoder_timeout', 120000),
            context={'cwd': cwd},
        )
        return await app.subagent_manager.execute(request)

    def _run_sync(coro):
        """同步执行协程，兼容已有事件循环。"""
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None
        if loop and loop.is_running():
            # 当前线程已有事件循环（如 FastAPI async handler），
            # 在新线程中创建独立循环执行，避免阻塞主循环
            import concurrent.futures
            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
                return pool.submit(asyncio.run, coro).result()
        return asyncio.run(coro)

    try:
        result = _run_sync(_run())
    except Exception as e:
        # 标记任务失败
        try:
            app.db.cas_transition(task_id, 'running', 'failed',
                                  message=str(e))
            app.db.update_task(task_id, error_type='exception',
                               error_message=str(e)[:500])
        except Exception:
            pass
        return {'success': False, 'error': 'Qoder 调用失败: %s' % e}

    # 更新任务状态
    try:
        if result.success:
            app.db.cas_transition(task_id, 'running', 'completed',
                                  message='Qoder 执行完成')
            app.db.update_task(
                task_id,
                result=result.output[:500] if result.output else None,
                completed_at=datetime.now().isoformat(),
                progress=100,
            )
        else:
            app.db.cas_transition(task_id, 'running', 'failed',
                                  message=result.error)
            app.db.update_task(
                task_id,
                error_type='qoder_error',
                error_message=(result.error or '')[:500],
            )
    except Exception:
        logger.debug('Qoder 任务状态更新失败（不影响结果）', exc_info=True)

    # 追加执行结果到日志
    try:
        with open(log_file, 'a') as f:
            f.write('--- 执行结果 ---\n')
            f.write('状态: %s\n' % ('成功' if result.success else '失败'))
            f.write('耗时: %.1fs\n' % (result.duration_ms / 1000))
            if result.success:
                f.write('输出摘要:\n%s\n' % result.output[:2000])
            else:
                f.write('错误: %s\n' % result.error)
    except OSError:
        pass

    if result.success:
        lines = [
            '═══ Qoder 执行完成 ═══',
            '任务 ID: %s' % task_id,
            '工作目录: %s' % cwd,
            '耗时: %.1fs' % (result.duration_ms / 1000),
            '─── 输出 ───',
            result.output,
        ]
        return '\n'.join(lines)
    else:
        return {'success': False, 'error': result.error or 'Qoder 执行失败'}


def stream_qoder(app, args_str=''):
    """流式版 Qoder 调用，yield ('reasoning', chunk) + 最终 ('content', result)。

    供 process_message_stream() 使用，将 Qoder CLI 的 stdout
    实时转发为 reasoning 事件，前端显示为思考过程。
    """
    import uuid
    import shutil
    import subprocess
    import time
    from pathlib import Path
    from datetime import datetime

    if app is None:
        yield ('content', 'AgentApp 未就绪')
        return
    if not args_str.strip():
        yield ('content', '用法: /qoder <任务描述>')
        return

    # 检查 qodercli 是否可用
    from ..core.tool_probe import find_binary_simple
    qoder_bin = app.config.get('qoder_command', 'qodercli')
    binary, status = find_binary_simple(qoder_bin)
    if not binary:
        yield ('content', 'Qoder CLI 未安装。请访问 https://qoder.com 下载安装')
        return

    # --- 与 cmd_qoder 相同的初始化逻辑 ---
    task_id = 'task-%s' % uuid.uuid4().hex[:12]
    task_ws = (Path(app.config.home) / 'workspace' / 'projects'
               / 'proj-default' / 'tasks' / task_id)
    task_ws.mkdir(parents=True, exist_ok=True)
    cwd = str(task_ws)

    # 创建任务日志文件
    log_file = task_ws / ('%s.log' % task_id)
    log_file.write_text(
        'Qoder 任务执行日志（流式）\n'
        '=========================\n'
        '任务 ID: %s\n'
        '创建时间: %s\n'
        '工作目录: %s\n'
        '任务描述: %s\n'
        '=========================\n\n' % (
            task_id,
            datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            task_ws,
            args_str.strip(),
        )
    )

    # DB 任务记录
    try:
        app.db.create_task(
            task_id=task_id, message=args_str.strip(),
            kind='chat', priority=5,
        )
        app.db.cas_transition(task_id, 'pending', 'running',
                              message='Qoder 开始执行（流式）')
    except Exception:
        logger.debug('stream_qoder 任务记录创建失败', exc_info=True)

    app._current_task_workspace = cwd

    # 构建 qodercli 命令（使用完整路径）
    cmd = [binary, '-p', args_str.strip()]
    cmd.extend(['--cwd', cwd])
    if app.config.get('qoder_yolo', True):
        cmd.append('--yolo')

    timeout_s = app.config.get('qoder_timeout', 120000) / 1000
    t0 = time.monotonic()

    # --- 流式执行：逐行读取 stdout ---
    output_lines = []
    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=cwd,
            text=True,
            bufsize=1,
        )

        # 逐行读取 stdout，每行作为 reasoning 事件 yield
        for line in proc.stdout:
            output_lines.append(line)
            yield ('reasoning', line)

        # 等待进程结束
        try:
            proc.wait(timeout=max(timeout_s, 10))
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait()
            yield ('content', '\nQoder 执行超时 (%.0fs)' % timeout_s)
            try:
                app.db.cas_transition(task_id, 'running', 'failed',
                                      message='执行超时')
            except Exception:
                pass
            return

        stdout_text = ''.join(output_lines)
        duration = time.monotonic() - t0

        if proc.returncode != 0:
            err_text = ''
            if proc.stderr:
                try:
                    err_text = proc.stderr.read() or ''
                except Exception:
                    pass
            # 标记任务失败
            try:
                app.db.cas_transition(task_id, 'running', 'failed',
                                      message='Qoder 执行失败 (exit %d)' % proc.returncode)
                app.db.update_task(task_id, error_type='qoder_error',
                                   error_message=(err_text or stdout_text)[:500])
            except Exception:
                pass
            # 追加日志
            try:
                with open(log_file, 'a') as f:
                    f.write('--- 执行结果 ---\n')
                    f.write('状态: 失败 (exit %d)\n' % proc.returncode)
                    f.write('耗时: %.1fs\n' % duration)
                    f.write('错误: %s\n' % (err_text or stdout_text)[:2000])
            except OSError:
                pass
            yield ('content', 'Qoder 执行失败 (exit %d): %s' % (
                proc.returncode, (err_text or stdout_text)[:500]))
            return

        # 成功：标记任务完成
        try:
            app.db.cas_transition(task_id, 'running', 'completed',
                                  message='Qoder 执行完成（流式）')
            app.db.update_task(
                task_id,
                result=stdout_text[:500],
                completed_at=datetime.now().isoformat(),
                progress=100,
            )
        except Exception:
            logger.debug('stream_qoder 任务状态更新失败', exc_info=True)

        # 追加日志
        try:
            with open(log_file, 'a') as f:
                f.write('--- 执行结果 ---\n')
                f.write('状态: 成功\n')
                f.write('耗时: %.1fs\n' % duration)
                f.write('输出摘要:\n%s\n' % stdout_text[:2000])
        except OSError:
            pass

        # 最终结果作为 content 输出
        yield ('content', '\n═══ Qoder 执行完成（任务 %s，耗时 %.1fs）═══\n' % (
            task_id, duration))
        yield ('content', stdout_text)

    except Exception as e:
        # 标记任务失败
        try:
            app.db.cas_transition(task_id, 'running', 'failed',
                                  message=str(e))
            app.db.update_task(task_id, error_type='exception',
                               error_message=str(e)[:500])
        except Exception:
            pass
        yield ('content', 'Qoder 调用失败: %s' % e)


def cmd_project(app, args_str=''):
    """/project — 快速创建项目并自动拆解子任务。"""
    if app is None:
        return {'success': False, 'error': 'AgentApp 未就绪'}
    if not args_str.strip():
        return ('用法: /project 项目名称 | 描述（可选）\n'
                '示例: /project 开发一个电商平台 | 包含商品管理和订单系统')

    # 解析标题和描述（用 | 分隔）
    parts = args_str.split('|', 1)
    title = parts[0].strip()
    description = parts[1].strip() if len(parts) > 1 else ''

    if not title:
        return {'success': False, 'error': '项目名称不能为空'}

    try:
        from agent_runtime.core.project_engine import ProjectEngine
        from agent_runtime.core.task_engine import TaskEngine
        task_engine = TaskEngine(
            db=app.db,
            ws_client=app.ws_client,
            agent_id=app.config.agent_id)
        engine = ProjectEngine(
            db=app.db,
            ws_client=app.ws_client,
            agent_id=app.config.agent_id,
            llm=app.llm,
            task_engine=task_engine,
            home=app.config.home)
        project = engine.create_project(
            title=title,
            description=description,
        )
        # 异步触发自动拆解
        engine.decompose_project_async(project['id'])
        lines = [
            '═══ 项目已创建（子任务拆解中）═══',
            'ID    : %s' % project.get('id', ''),
            '标题  : %s' % project.get('title', ''),
            '状态  : %s' % project.get('status', ''),
            '类型  : %s' % project.get('plan_type', 'dag'),
        ]
        if description:
            lines.append('描述  : %s' % description)
        lines.append('')
        lines.append('⏳ 子任务正在自动拆解中，请稍后查看...')
        return '\n'.join(lines)
    except Exception as e:
        return {'success': False, 'error': '创建项目失败: %s' % e}


def _resolve_qoder_cwd(app, task_id=None, project_id=None):
    """解析 Qoder 工作目录。

    优先级：
    1. app._current_task_workspace（任务引擎注入的任务专属工作空间）
    2. task_id 指定时 → {home}/workspace/projects/{project_id}/tasks/{task_id}/
    3. workspace_dirs 第一项（~/workspace）
    4. ~/workspace（兜底）

    目录不存在时自动创建。
    """
    from pathlib import Path
    home = Path(app.config.home)

    # 任务引擎执行时注入的任务专属工作空间
    task_ws = getattr(app, '_current_task_workspace', None)
    if task_ws:
        Path(task_ws).mkdir(parents=True, exist_ok=True)
        return task_ws

    if task_id:
        proj = project_id or 'proj-default'
        task_ws = home / 'workspace' / 'projects' / proj / 'tasks' / task_id
        task_ws.mkdir(parents=True, exist_ok=True)
        return str(task_ws)

    # 使用 workspace_dirs 第一项
    ws_dirs = getattr(app.config, 'workspace_dirs', [])
    for entry in ws_dirs:
        p = Path(entry.get('path', ''))
        if p.exists() or str(p) != str(home):
            p.mkdir(parents=True, exist_ok=True)
            return str(p)

    # 兜底
    fallback = home / 'workspace'
    fallback.mkdir(parents=True, exist_ok=True)
    return str(fallback)


