def register_builtin_commands(registry):
    """把全部内置命令注册到 CommandRegistry。"""
    builtins = [
        ('/status',   cmd_status,   '查看 agent 运行时状态', False, '/status'),
        ('/skills',   cmd_skills,   '列出已装备的技能', False, '/skills'),
        ('/reload',   cmd_reload,   '重新扫描 skills / metaskills', False, '/reload'),
        ('/learn',    cmd_learn,    '触发探索期：生成新 Skill Package', True, '/learn'),
        ('/explore',  cmd_explore,  '手动探索技能（同 /learn）', True, '/explore "生成日报"'),
        ('/fallback', cmd_fallback, '诊断最近一次失败', False, '/fallback'),
        ('/trace',    cmd_trace,    '查看最近 DAG 执行轨迹', False, '/trace'),
        ('/qoder',    cmd_qoder,    '调用 Qoder CLI 子 Agent 执行开发任务', False, '/qoder 写一个冒泡排序'),
        ('/project',  cmd_project,  '快速创建项目', False, '/project 开发一个电商平台'),
        ('/help',     cmd_help,     '列出所有可用命令', False, '/help'),
    ]
    for name, handler, desc, require_llm, example in builtins:
        registry.register(name, handler, description=desc,
                          require_llm=require_llm, usage_example=example)
